    internal static int TZeros(emon.Port.Cells c, int n) {
        // Append n zeros: the words of two SHA-256s, or a residency map with nothing resident.
        int i = 0;
        while (i < n) {
            emon.Port.CellsPush(c, 0);
            i += 1;
        }
        return 0;
    }
